function hgDef(){return 'https://thu.xxbgwypx.cc'}
function hgPubs(){return ['https://huangguoai.pages.dev/publish.js','https://hu-guo.pages.dev/publish.js']}
function hgSubs(){return ['thu','pku','fdu','sjtu','zju','nju','xmu','sysu','whu','jlu','scu','ruc','bnu','nku','tju','sdu','hust','xjtu','hit']}
function hgRoots(){return ['xxbgwypx.cc']}
function hgHost(u){var s=hgST(u).replace(/^https?:\/\//,'');var i=s.indexOf('/');return i>0?s.substring(0,i):s}
function hgShort(h){h=String(h||'');var d=h.split('.');var t=d[0]||h;if(t.length>13)t=t.substring(0,13);return t}
function hgGV(k,dv){var v='';try{v=String(source.get(k)||'')}catch(e){}
  if(!v||v=='null'||v=='undefined')v=dv;return v?hgST(v):''}
function hgSV(k,v){try{source.put(k,String(v))}catch(e){}}
function hgT(t){try{java.longToast(t)}catch(e){try{java.toast(t)}catch(e2){}}}
function hgSites(){var r=hgGV('hg_sites','');var a=[];if(r){try{a=JSON.parse(r)}catch(e){}}return a}
function hgRootSort(roots){
  var pri=[],last=[];
  for(var i=0;i<roots.length;i++){
    var r=roots[i];
    if(r.indexOf('arj2ftl0')>=0||r.indexOf('40ygo615')>=0||r.indexOf('h2na6qa39')>=0||r.indexOf('jxqgmx5ga')>=0)last.push(r);
    else pri.push(r);
  }
  return pri.concat(last)}
function hgCand(){
  var roots=hgRoots();
  var ph='';
  var pubs=hgPubs();
  var pv=hgGV('pub','');
  if(pv.indexOf('http')===0)pubs=[pv].concat(pubs);
  for(var pi=0;pi<pubs.length;pi++){
    try{ph=String(java.ajax(pubs[pi]+',{"timeout":8000,"retry":0}'))}catch(e){}
    if(ph.length>500)break;
  }
  if(ph.length>500){
    var m=ph.match(/var\s+urls\s*=\s*\[([\s\S]*?)\]/);
    if(m){var re=/['"]([a-z0-9.\-]+\.[a-z]{2,}\/?)['"]/gi,mm;
      var pr=[];
      while((mm=re.exec(m[1]))!=null)pr.push(mm[1].replace(/\/+$/,''));
      if(pr.length)roots=pr;
    }
  }
  roots=hgRootSort(roots);
  var cs=[];
  for(var i=0;i<roots.length;i++)for(var j=0;j<hgSubs().length;j++)cs.push('https://'+hgSubs()[j]+'.'+roots[i]);
  cs.push(hgDef());
  var seen={},ls=[];
  for(var m2=0;m2<cs.length;m2++){if(!seen[cs[m2]]){seen[cs[m2]]=1;ls.push(cs[m2])}}
  return ls}
function hgBatchProbe(urls){
  var rows=[];
  var res=null;
  try{res=java.ajaxAll(urls,true)}catch(e1){if(urls&&urls.length===1){}else{try{res=java.ajaxAll(urls)}catch(e2){}}}
  if(!res&&urls&&urls.length===1){
    try{var b=String(java.ajax(urls[0]+',{"timeout":8000,"retry":0}'));if(b.length>20000&&b.indexOf('Exception')<0)rows.push({url:urls[0],host:hgHost(urls[0]),ms:0,fin:''})}catch(e3){}
    return rows}
  if(res){
    for(var k=0;k<res.length;k++){
      var code=-9,ms=-1,bl=0,fin='',bod='';
      try{code=res[k].raw().code()}catch(e){}
      try{ms=res[k].callTime()}catch(e){}
      try{bod=String(res[k].body());bl=bod.length}catch(e){}
      try{var ss=String(res[k].raw().toString());var fm=ss.match(/url=(\S+?)\}/);if(fm)fin=fm[1]}catch(e){}
      var isErr=(bod.indexOf('Exception')>=0&&bl<3000);
      if(code>=200&&code<400&&bl>20000&&!isErr)rows.push({url:urls[k],host:hgHost(urls[k]),ms:ms,fin:fin});
    }
  }
  return rows}
function FQ_siteName(i){
  try{
    var a=hgSites();
    if(!a.length)return '线路'+(i+1);
    if(i>=a.length)return '';
    var s=a[i];
    var cur=hgGV('hg_line',hgDef());
    return hgShort(s.host)+' '+s.ms+'ms'+(s.url===cur?' ✓':'');
  }catch(e){return '线路'+(i+1)}
}
function FQ_hgGo(){
  try{
    var t0=Date.now();
    var p=hgGV('pub',hgPubs()[0]);
    if(!p||p.indexOf('http')!=0){hgT('发布页地址无效：需以 http:// 或 https:// 开头');return}
    hgT('正在抓取发布页并测速...');
    var ls=hgCand();
    var rows=[];
    var B=10,NEED=12;
    for(var b=0;b<ls.length&&rows.length<NEED;b+=B){
      var batch=ls.slice(b,b+B);
      var bu=[];
      for(var q=0;q<batch.length;q++)bu.push(batch[q]+'/');
      var got=hgBatchProbe(bu);
      for(var g=0;g<got.length&&rows.length<NEED;g++)rows.push(got[g]);
    }
    if(!rows.length){hgT('测速完成：'+ls.length+' 条线路全部不可用'+hgNL()+'耗时 '+((Date.now()-t0)/1000).toFixed(1)+' 秒');return}
    rows.sort(function(x,y){return x.ms-y.ms});
    hgSV('hg_sites',JSON.stringify(rows));
    hgSV('hg_line',rows[0].url);
    hgSV('hg_line_ts',String(Date.now()));
    hgSV('hg_line_chk',String(Date.now()));
    hgT('测速完成（'+ls.length+' 条，可用 '+rows.length+' 条，耗时 '+((Date.now()-t0)/1000).toFixed(1)+' 秒）'+hgNL()+'已选最快：'+rows[0].host+'（'+rows[0].ms+'ms）'+hgNL()+'若按钮名未刷新，重新打开本面板即可');
    try{java.reLoginView(false)}catch(e){}
  }catch(e){hgT('测速失败：'+String(e).substring(0,100))}
}
function FQ_hgPick(i){
  try{
    var a=hgSites();
    if(!a.length||!a[i]){
      hgT('该线路尚未测速，请先点「获取网址并测速」');
      return;
    }
    hgSV('hg_line',a[i].url);
    hgSV('hg_line_ts',String(Date.now()));
    hgSV('hg_line_chk',String(Date.now()));
    hgT('已选择网站：'+a[i].host+hgNL()+'延迟：'+a[i].ms+'ms');
    try{java.reLoginView(false)}catch(e){}
  }catch(e){hgT('切换失败：'+String(e).substring(0,80))}
}
function FQ_hgCur(){
  try{hgT('当前线路：'+hgGV('hg_line',hgDef()))}catch(e){}
}
function FQ_hgChk(){
  try{
    var L=hgGV('hg_line',hgDef());
    var h='';
    try{h=String(java.ajax(L+'/profile/,{"timeout":8000,"retry":0}'))}catch(e){}
    if(h.length<2000||(h.indexOf('Exception')>=0&&h.length<3000)){hgT('无法连接线路：'+L+hgNL()+'请检查网络或切换线路');return}
    var guest=h.indexOf('data-auth-open='+hgQ('login')+'>'+String.fromCharCode(30331,24405,47,27880,20876))>=0;
    var dash=h.indexOf('ID'+String.fromCharCode(65306)+String.fromCharCode(8212))>=0;
    var out=h.indexOf(String.fromCharCode(36864,20986))>=0||h.indexOf('signOut')>=0||h.indexOf('logout')>=0;
    if(guest&&dash)hgT('游客状态（未登录）'+hgNL()+'搜索/详情/目录/播放均可正常使用'+hgNL()+'登录后可看收藏与观看历史'+hgNL()+'当前线路：'+L);
    else if(out)hgT('已登录'+hgNL()+'当前线路：'+L);
    else hgT('状态未知（页面结构可能已变化）'+hgNL()+'当前线路：'+L);
  }catch(e){hgT('检查失败：'+String(e).substring(0,80))}
}
function FQ_hgRst(){
  try{
    hgSV('pub',hgPubs()[0]);hgSV('hg_line',hgDef());hgSV('hg_line_ts','0');hgSV('hg_line_chk','0');hgSV('hg_sites','');
